const cfg=$input.first().json??{};
const notionRootUrl=String(cfg.notionRootUrl??'').trim();
if(!notionRootUrl){
  return [{json:{enabled:false,status:'not-configured',pagesProcessed:0,contentHash:null,collectedAt:null,truncated:false,pages:[]}}];
}
const matches=notionRootUrl.match(/[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/ig)??[];
if(matches.length===0){
  throw new Error('Página raiz do Notion inválida. Informe a URL completa ou um page ID UUID.');
}
const compact=matches[matches.length-1].replace(/-/g,'').toLowerCase();
const rootPageId=[compact.slice(0,8),compact.slice(8,12),compact.slice(12,16),compact.slice(16,20),compact.slice(20)].join('-');
const bounded=(value,fallback,min,max)=>Math.min(max,Math.max(min,Number(value)||fallback));
return [{json:{
  enabled:true,
  status:'configured',
  rootPageId,
  maxPages:bounded(cfg.maxPages,100,1,500),
  maxCharsPerPage:bounded(cfg.maxCharsPerPage,20000,1000,100000),
  maxSummaryCharsPerPage:bounded(cfg.maxSummaryCharsPerPage,4000,1000,12000),
  maxTotalChars:bounded(cfg.maxTotalChars,40000,5000,200000),
  notionApiVersion:String(cfg.notionApiVersion??'2026-03-11')
}}];

const cfg=$('Validar página raiz').first().json;
const blocks=$input.all().flatMap(item=>Array.isArray(item.json?.results)?item.json.results:[]);
const seen=new Set();
const childPages=[];
for(const block of blocks){
  if(block?.type!=='child_page'||!block.id||seen.has(block.id)) continue;
  seen.add(block.id);
  childPages.push({
    pageId:block.id,
    title:String(block.child_page?.title??'Reunião sem título').trim()||'Reunião sem título',
    lastEditedTime:block.last_edited_time??null
  });
}
if(childPages.length===0){
  throw new Error('Nenhuma subpágina de reunião foi encontrada diretamente na página raiz. Confirme o link e compartilhe a página e suas subpáginas com a integração do Notion.');
}
const limited=childPages.slice(0,cfg.maxPages);
return limited.map(page=>({json:{
  ...page,
  isRoot:false,
  pagesDiscovered:childPages.length,
  pagesLimitApplied:childPages.length>limited.length,
  rootBlocksScanned:blocks.length,
  maxCharsPerPage:cfg.maxCharsPerPage,
  maxSummaryCharsPerPage:cfg.maxSummaryCharsPerPage,
  maxTotalChars:cfg.maxTotalChars
}}));

const page=$('Loop por página').item.json;
const redact=value=>String(value??'')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/=\-]+/gi,'Bearer {{REDACTED_TOKEN}}')
  .replace(/\b(?:gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9_-]{16,}|secret_[A-Za-z0-9_-]{16,})\b/g,'{{REDACTED_TOKEN}}')
  .replace(/((?:api[_ -]?key|access[_ -]?token|token|secret|password|senha)\s*[:=]\s*)[^\s\x60\"'<>]+/gi,'$1{{REDACTED_VALUE}}')
  .replace(/https?:\/\/(?:localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+)(?::\d+)?/gi,'https://internal.example');
let markdown=redact($json.markdown??'').trim();
let pageTruncated=Boolean($json.truncated);
if(markdown.length>page.maxCharsPerPage){
  const head=Math.floor(page.maxCharsPerPage*0.7);
  const tail=page.maxCharsPerPage-head;
  markdown=markdown.slice(0,head)+'\n\n[... conteúdo intermediário truncado pelo coletor ...]\n\n'+markdown.slice(-tail);
  pageTruncated=true;
}
return {json:{
  title:String(page.title??'Página do Notion').replace(/[\r\n]+/g,' ').trim(),
  lastEditedTime:page.lastEditedTime,
  isRoot:Boolean(page.isRoot),
  markdown,
  pageTruncated,
  unknownBlocks:Array.isArray($json.unknown_block_ids)?$json.unknown_block_ids.length:0,
  pagesDiscovered:page.pagesDiscovered,
  pagesLimitApplied:page.pagesLimitApplied,
  maxSummaryCharsPerPage:page.maxSummaryCharsPerPage,
  maxTotalChars:page.maxTotalChars
}};

const source=$('Sanitizar página do Notion').item.json;
const maxSummaryChars=Math.max(1000,Number(source.maxSummaryCharsPerPage??4000));
let summary=String($json.output??$json.text??'').trim();
const summaryFailed=Boolean($json.error)||!summary;
if(summaryFailed){
  const excerpt=String(source.markdown??'').slice(0,Math.min(maxSummaryChars,3000)).trim();
  summary='## Resumo indisponível\n\nA sumarização por IA falhou para esta reunião. Revise a fonte original no Notion.\n\n## Trecho sanitizado para contingência\n\n'+(excerpt||'Nenhum conteúdo textual foi recuperado.');
}
let summaryTruncated=false;
if(summary.length>maxSummaryChars){
  summary=summary.slice(0,maxSummaryChars)+'\n\n[... resumo truncado pelo limite configurado ...]';
  summaryTruncated=true;
}
return {json:{
  title:source.title,
  lastEditedTime:source.lastEditedTime,
  isRoot:source.isRoot,
  markdown:summary,
  summarized:!summaryFailed,
  summaryFallback:summaryFailed,
  pageTruncated:Boolean(source.pageTruncated)||summaryTruncated,
  unknownBlocks:source.unknownBlocks,
  pagesDiscovered:source.pagesDiscovered,
  pagesLimitApplied:source.pagesLimitApplied,
  maxTotalChars:source.maxTotalChars
}};

const inputPages=$input.all().map(item=>item.json??{});
const pages=[];
const maxTotalChars=Number(inputPages[0]?.maxTotalChars??40000);
let used=0;
let totalTruncated=false;
for(const page of inputPages){
  if(!page.markdown) continue;
  const remaining=maxTotalChars-used;
  if(remaining<=0){totalTruncated=true;break;}
  let markdown=String(page.markdown);
  if(markdown.length>remaining){markdown=markdown.slice(0,remaining)+'\n\n[... limite total do contexto atingido ...]';totalTruncated=true;}
  used+=markdown.length;
  pages.push({
    title:page.title,
    lastEditedTime:page.lastEditedTime,
    isRoot:page.isRoot,
    markdown,
    summarized:Boolean(page.summarized),
    summaryFallback:Boolean(page.summaryFallback)
  });
}
const stableHash=value=>{
  const text=String(value??'');
  let first=2166136261;
  let second=3339675911;
  for(let index=0;index<text.length;index++){
    const code=text.charCodeAt(index);
    first=Math.imul(first^code,16777619);
    second=Math.imul(second^code,2246822519);
  }
  return (first>>>0).toString(16).padStart(8,'0')+(second>>>0).toString(16).padStart(8,'0');
};
const summaryFallbacks=inputPages.filter(page=>page.summaryFallback).length;
const truncated=totalTruncated||inputPages.some(page=>page.pageTruncated||page.pagesLimitApplied||page.unknownBlocks>0);
return [{json:{notionContext:{
  enabled:true,
  status:summaryFallbacks?'collected-with-summary-fallback':'collected-and-summarized',
  collectedAt:new Date().toISOString(),
  pagesProcessed:pages.length,
  pagesDiscovered:Number(inputPages[0]?.pagesDiscovered??pages.length),
  summarized:true,
  summarizedPages:pages.filter(page=>page.summarized).length,
  summaryFallbacks,
  contentHash:stableHash(pages.map(page=>[page.title,page.lastEditedTime,page.markdown].join('\n')).join('\n---\n')),
  truncated,
  contentPublished:false,
  pages
}}}];

const source=$input.first().json??{};
